import { escapeInterpolatedHtmlValue } from '../image-worker/source/packages/stx/src/expressions.ts'
const cases = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'))
const source = '<input {{ attributes }}>'
for (const {raw,accepted} of cases) {
  let result,refused=false
  try { result=escapeInterpolatedHtmlValue(source,source.indexOf('{{'),raw,false,'{{ attributes }}'.length) }
