import { skipLeadingHtmlTrivia } from '../image-worker/source/packages/stx/src/html-masking.ts'
const legacy=/^(\s*(?:(?:<!--[\s\S]*?-->|\x00STX_HTML_COMMENT_\d+\x00)\s*)*)/
const parts=['',' ','\n\t','<!-- a -->','\x00STX_HTML_COMMENT_123\x00','<!-- b --><!-- c -->']
const tails=['<span>root</span>','text --><span>root</span>','<!-- unfinished','\x00STX_HTML_COMMENT_nope\x00<span>root</span>','']
let cases=0
for(let i=0;i<7776;i++){
 let n=i,prefix=''
 for(let j=0;j<5;j++){prefix+=parts[n%parts.length];n=Math.floor(n/parts.length)}
 for(const tail of tails){
  const html=prefix+tail
  const expected=legacy.exec(html)[0].length
  const actual=skipLeadingHtmlTrivia(html)
  if(actual!==expected)throw new Error(JSON.stringify({html,expected,actual}))
  cases++
 }
}
console.log(JSON.stringify({cases,mismatches:0,oracle:process.version}))

